{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="theme-color" content="#8A5A3C">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Health Topics</a>
        <a href="/approach.html">Our Way</a>
        <a href="/pricing.html">Membership</a>
        <a href="/about.html">Team</a>
        <a href="/book.html">Schedule</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <div class="header-ctas">
        <a class="phone" href="tel:{{PHONE}}">{{PHONE}}</a>
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1>Thoughtful, whole-person care that fits into daily life</h1>
          <p class="lead">We integrate evidence-aware modalities across nutrition, stress, movement, and sleep so you can make sustainable changes without overwhelm.</p>
          <p class="muted">A membership model for steady progress, personalized visits, and guided self-practice.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Meet the team</a>
          </div>
        </div>
        <aside class="hero-panel">
          <h3>Quick planner — build a session</h3>
          <form id="session-planner" class="planner">
            <label>Primary concern
              <input name="concern" placeholder="e.g., sleep, digestion, stress" />
            </label>
            <label>Top goal
              <input name="goal" placeholder="A simple, measurable aim" />
            </label>

            <fieldset class="modalities">
              <legend>Prefered focus (choose up to 3)</legend>
              <label><input type="checkbox" name="modality" value="Nutrition"> Nutrition</label>
              <label><input type="checkbox" name="modality" value="Movement"> Movement</label>
              <label><input type="checkbox" name="modality" value="Sleep"> Sleep</label>
              <label><input type="checkbox" name="modality" value="Mind-Body"> Mind-Body</label>
              <label><input type="checkbox" name="modality" value="Herbal" disabled> Herbal (by consult)</label>
            </fieldset>

            <label>Session length
              <select name="length"><option>30</option><option selected>50</option><option>75</option></select>
            </label>
            <label>Suggested frequency
              <select name="freq"><option>Weekly</option><option selected>Biweekly</option><option>Monthly</option></select>
            </label>
            <div class="planner-actions">
              <button type="button" id="build-plan" class="btn primary">Build my plan</button>
              <button type="button" id="copy-plan" class="btn ghost" disabled>Copy summary</button>
              <button type="button" id="download-plan" class="btn ghost" disabled>Download .txt</button>
            </div>
          </form>
          <pre id="plan-output" class="plan-output" aria-live="polite"></pre>
        </aside>
      </div>
    </section>

    <!-- Benefits (reordered on purpose) -->
    <section class="benefits wrap">
      <h2>How our membership helps you</h2>
      <div class="grid">
        <div class="card">
          <h3>Ongoing guidance</h3>
          <p>Monthly visits plus targeted check-ins to keep changes practical and measurable.</p>
        </div>
        <div class="card">
          <h3>Personal toolkit</h3>
          <p>Tailored plans, simple practices, and clear measures to follow at home.</p>
        </div>
        <div class="card">
          <h3>Interdisciplinary thinking</h3>
          <p>We draw on nutrition, behavior, sleep science, and movement to make plans that add up.</p>
        </div>
      </div>
    </section>

    <!-- Social proof -->
    <section class="social-proof wrap">
      <h2>Voices from members</h2>
      <blockquote>
        "I appreciate the steady check-ins and specific actions each month — I actually see change."<cite>— Member, {{CITY}}</cite>
      </blockquote>
      <blockquote>
        "Practical ideas that fit real life. The team listens and then helps prioritize."<cite>— Participant, {{STATE}}</cite>
      </blockquote>
    </section>

    <!-- Process including Whole-person inventory -->
    <section class="process wrap">
      <h2>How a typical consultation unfolds</h2>
      <ol>
        <li>We listen to what matters right now and map immediate opportunities.</li>
        <li>We co-create a short plan with simple practices and measurable signs.</li>
        <li>We check back at set intervals and adapt based on results and new priorities.</li>
      </ol>

      <div class="inventory">
        <h3>Whole-person inventory</h3>
        <p>Check areas that feel relevant and get a suggested consultation agenda and a follow-up cadence.</p>
        <form id="inventory-form">
          <div class="inventory-grid">
            <label><input type="checkbox" name="area" value="Sleep"> Sleep and rest</label>
            <label><input type="checkbox" name="area" value="Digestion"> Digestion and appetite</label>
            <label><input type="checkbox" name="area" value="Energy"> Energy and fatigue</label>
            <label><input type="checkbox" name="area" value="Mood"> Mood and resilience</label>
            <label><input type="checkbox" name="area" value="Movement"> Movement and strength</label>
            <label><input type="checkbox" name="area" value="Breathing"> Breathing and relaxation</label>
            <label><input type="checkbox" name="area" value="Environment"> Home and work patterns</label>
            <label><input type="checkbox" name="area" value="Medications"> Medications and supplements</label>
          </div>
          <div class="inventory-actions">
            <button type="button" id="build-agenda" class="btn primary">Create agenda</button>
            <button type="button" id="copy-agenda" class="btn ghost" disabled>Copy agenda</button>
          </div>
        </form>
        <pre id="agenda-output" class="plan-output" aria-live="polite"></pre>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq wrap">
      <h2>FAQ</h2>
      <details>
        <summary>Do you cure conditions?</summary>
        <p>We do not promise cures. Our approach is educational and integrative: we partner with you to reduce symptoms, improve function, and support better self-care.</p>
      </details>
      <details>
        <summary>What about prescriptions?</summary>
        <p>We coordinate with your prescribers as needed. Some services may involve suggestions best handled by your primary clinician.</p>
      </details>
    </section>

    <!-- CTA -->
    <section class="final-cta wrap">
      <h2>Ready to start steady, practical change?</h2>
      <p>Begin with a short planning visit and a personalized agenda.</p>
      <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-inner">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
    <svg class="pattern-bg" aria-hidden="true"><use href="assets/img/pattern.svg#p"></use></svg>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
{"path":"assets/css/styles.css","content":":root{
  --bg:#FBF6F1;
  --card:#fff7f2;
  --accent:#8A5A3C;
  --accent-2:#C78A64;
  --muted:#6B5A4A;
  --radius:10px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;background:var(--bg);color:var(--muted)}
.wrap{max-width:var(--max-width);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,var(--card),var(--bg));border-bottom:1px solid rgba(138,90,60,0.06)}
.header-inner{display:flex;align-items:center;gap:18px}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.15rem}
.main-nav{display:flex;gap:10px;margin-left:12px}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:6px}
.main-nav a:hover{background:rgba(200,138,100,0.08)}
.header-ctas{margin-left:auto;display:flex;align-items:center;gap:12px}
.header-ctas .phone{color:var(--muted);text-decoration:none}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;text-decoration:none;border:1px solid transparent;font-weight:600}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border-color:rgba(138,90,60,0.12);color:var(--accent)}
.hero{padding:32px 0;background:linear-gradient(180deg,rgba(202,152,118,0.06),transparent)}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:start}
.hero-copy h1{margin:0 0 10px 0;color:var(--accent);font-size:1.6rem}
.lead{color:var(--muted);margin:0 0 8px 0}
.hero-panel{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:0 6px 18px rgba(138,90,60,0.06)}
.planner label{display:block;font-size:0.9rem;margin-bottom:8px}
.planner input[type="text"],.planner input[type="search"],.planner select{width:100%;padding:8px;border-radius:6px;border:1px solid rgba(107,90,74,0.08);background:#fff}
.modalities{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:8px 0}
.planner-actions{display:flex;gap:8px;margin-top:10px}
.plan-output{background:#fff;padding:12px;border-radius:8px;border:1px dashed rgba(138,90,60,0.08);min-height:80px;white-space:pre-wrap}
.benefits .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.card{background:linear-gradient(180deg,#fff,#fff7f0);padding:16px;border-radius:8px;border:1px solid rgba(138,90,60,0.04)}
.social-proof blockquote{background:#fff;padding:14px;border-left:4px solid var(--accent-2);border-radius:6px;margin:10px 0}
.process ol{padding-left:16px}
.inventory{margin-top:12px}
.inventory-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.inventory label{background:#fff;padding:8px;border-radius:6px;border:1px solid rgba(107,90,74,0.04)}
.inventory-actions{margin-top:10px}
.faq details{background:#fff;padding:12px;border-radius:8px;border:1px solid rgba(138,90,60,0.04);margin-bottom:8px}
.final-cta{text-align:center;padding:28px 0}
.site-footer{border-top:1px solid rgba(138,90,60,0.06);padding:16px 0;background:linear-gradient(180deg,transparent,rgba(138,90,60,0.02))}
.footer-inner{display:flex;justify-content:space-between;align-items:center}
.pattern-bg{width:0;height:0;position:absolute;left:-9999px}
@media(max-width:880px){
  .hero-inner{grid-template-columns:1fr}
  .main-nav{display:none}
  .benefits .grid{grid-template-columns:1fr}
  .inventory-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Session Planner
  const buildBtn = document.getElementById('build-plan');
  const copyPlanBtn = document.getElementById('copy-plan');
  const downloadPlanBtn = document.getElementById('download-plan');
  const planOutput = document.getElementById('plan-output');
  const sessionForm = document.getElementById('session-planner');

  function gatherPlanner(){
    const form = sessionForm;
    const concern = form.concern.value.trim() || 'Not specified';
    const goal = form.goal.value.trim() || 'Short-term improvement';
    const length = form.length.value;
    const freq = form.freq.value;
    const modalities = Array.from(form.querySelectorAll('input[name="modality"]:checked')).map(n=>n.value);
    return {concern,goal,length,freq,modalities};
  }

  function synthesizePlan(data){
    const now = new Date().toLocaleDateString();
    let plan = `Plan generated: ${now}\n`;
    plan += `Primary concern: ${data.concern}\n`;
    plan += `Top goal: ${data.goal}\n`;
    plan += `Session: ${data.length} minutes, suggested cadence: ${data.freq}\n`;
    if(data.modalities.length){
      plan += `Focus areas: ${data.modalities.join(', ')}\n`;
    } else {
      plan += `Focus areas: general whole-person review\n`;
    }
    plan += '\nSuggested first-visit agenda:\n';
    plan += '- Brief history and current routines (15 minutes)\n';
    plan += '- Target 2-3 specific, measurable actions\n';
    plan += '- Simple tracking plan and one check-in metric\n';
    plan += '\nHome practices (first 2 weeks):\n';
    if(data.modalities.includes('Sleep')) plan += '- Nighttime routine adjustments, 1 consistent bedtime\n';
    if(data.modalities.includes('Nutrition')) plan += '- 1 small meal habit change, simple journal\n';
    if(data.modalities.includes('Movement')) plan += '- 10–20 min daily movement practice\n';
    if(data.modalities.includes('Mind-Body')) plan += '- 5 minutes breathing or body scan daily\n';
    plan += '\nFollow-up suggestion: ' + (data.freq==='Weekly' ? 'Weekly check-ins for 4 weeks, then re-evaluate' : (data.freq==='Biweekly' ? 'Biweekly check-ins for 2–3 sessions, then monthly' : 'Monthly check-ins for 3 months')) + '\n';
    plan += '\nNotes: This is an educational plan. Discuss medications and diagnoses with your clinician.';
    return plan;
  }

  function enableCopyDownload(){
    copyPlanBtn.disabled = false;
    downloadPlanBtn.disabled = false;
  }

  buildBtn && buildBtn.addEventListener('click', function(){
    const data = gatherPlanner();
    const text = synthesizePlan(data);
    planOutput.textContent = text;
    enableCopyDownload();
  });

  copyPlanBtn && copyPlanBtn.addEventListener('click', async function(){
    if(!planOutput.textContent) return;
    try{
      await navigator.clipboard.writeText(planOutput.textContent);
      copyPlanBtn.textContent = 'Copied';
      setTimeout(()=>copyPlanBtn.textContent='Copy summary',1500);
    }catch(e){
      copyPlanBtn.textContent = 'Copy failed';
    }
  });

  downloadPlanBtn && downloadPlanBtn.addEventListener('click', function(){
    if(!planOutput.textContent) return;
    const blob = new Blob([planOutput.textContent],{type:'text/plain;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'session-plan.txt';
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  });

  // Whole-person inventory
  const buildAgendaBtn = document.getElementById('build-agenda');
  const copyAgendaBtn = document.getElementById('copy-agenda');
  const agendaOutput = document.getElementById('agenda-output');
  const inventoryForm = document.getElementById('inventory-form');

  function gatherInventory(){
    const checks = Array.from(inventoryForm.querySelectorAll('input[name="area"]:checked')).map(n=>n.value);
    return checks;
  }

  function createAgenda(areas){
    const now = new Date().toLocaleDateString();
    if(areas.length===0){
      return `No areas selected. Consider a broad review visit to build priorities.\n\nSuggested cadence: Initial review, then biweekly brief check-ins until a routine is stable.`;
    }
    let agenda = `Whole-person inventory result: ${now}\n`;
    agenda += `Selected areas: ${areas.join(', ')}\n\n`;
    agenda += 'Prioritized consultation agenda:\n';
    // Prioritize by perceived organ-system clusters
    const priorityMap = {
      'Sleep':1,'Energy':2,'Mood':3,'Digestion':2,'Movement':3,'Breathing':1,'Environment':2,'Medications':1
    };
    areas.sort((a,b)=> (priorityMap[a]||5)-(priorityMap[b]||5));
    areas.forEach((a,i)=>{
      agenda += `${i+1}. ${a} — brief review, targeted questions, one immediate action\n`;
    });

    // follow-up cadence heuristic
    let cadence = 'Monthly check-ins';
    if(areas.length>=5) cadence = 'Biweekly check-ins for 6–8 weeks, then monthly';
    else if(areas.length>=3) cadence = 'Biweekly check-ins for 3 sessions, then monthly';
    else cadence = 'Monthly check-ins with a brief 10–15 minute check-in in 2 weeks if needed';

    agenda += `\nSuggested follow-up cadence: ${cadence}\n`;
    agenda += '\nBrief tools to prepare: a 3-day routine log (sleep, meals, mood) and a medication/supplement list.';
    return agenda;
  }

  buildAgendaBtn && buildAgendaBtn.addEventListener('click', function(){
    const areas = gatherInventory();
    const text = createAgenda(areas);
    agendaOutput.textContent = text;
    copyAgendaBtn.disabled = false;
  });

  copyAgendaBtn && copyAgendaBtn.addEventListener('click', async function(){
    if(!agendaOutput.textContent) return;
    try{
      await navigator.clipboard.writeText(agendaOutput.textContent);
      copyAgendaBtn.textContent = 'Copied';
      setTimeout(()=>copyAgendaBtn.textContent='Copy agenda',1500);
    }catch(e){
      copyAgendaBtn.textContent = 'Copy failed';
    }
  });

})();
"} 
